import{_ as r,o as a,c as t,a5 as s}from"./chunks/framework.CslsFoWx.js";const o="/VendoraSystem-docs/captures/2026-11-22-import-prealable/01-nouveaux-produits-pour.webp",i="/VendoraSystem-docs/captures/2026-11-22-import-prealable/02-apercu-creations.webp",c="/VendoraSystem-docs/captures/2026-11-22-import-prealable/03-confirmation-tva.webp",n="/VendoraSystem-docs/captures/2026-11-22-import-prealable/04-notes-magasin.webp",l="/VendoraSystem-docs/captures/2026-11-22-import-prealable/05-catalogue-a-change.webp",d="/VendoraSystem-docs/captures/2026-11-22-import-prealable/06-journal-import-csv.webp",u="/VendoraSystem-docs/captures/2026-11-22-import-prealable/07-apercu-magasin-tunis.webp",T=JSON.parse('{"title":"Import CSV du catalogue (préalable) — preuves sur la vraie stack (22/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-22-import-prealable.md","filePath":"generated/preuves/2026-11-22-import-prealable.md","lastUpdated":null}'),p={name:"preuves/2026-11-22-import-prealable.md"};function m(g,e,b,h,v,f){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="import-csv-du-catalogue-prealable-—-preuves-sur-la-vraie-stack-22-11-2026" tabindex="-1">Import CSV du catalogue (préalable) — preuves sur la vraie stack (22/11/2026) <a class="header-anchor" href="#import-csv-du-catalogue-prealable-—-preuves-sur-la-vraie-stack-22-11-2026" aria-label="Permalink to &quot;Import CSV du catalogue (préalable) — preuves sur la vraie stack (22/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-22-import-prealable</code> · 0 image(s) · 0 trace(s)</p><div><p>Ticket Linear VEN-50 « Import CSV : périmètre, TVA, magasin » (fiche <code>docs/lots/IMPORT-PREALABLE.md</code>, critères 13 à 15 ; spec 03).</p><p><strong>Stack</strong> : serveur construit depuis <code>main</code> (<code>e8ded5d02</code>, migrations jusqu&#39;à V138) sur le port 8097 et base neuve <code>pos_cip</code>, back-office <code>ng serve</code> sur le port 4217 (proxy vers 8097). Commerce de démo « Le Petit Bistrot (démo) » (semé par <code>help/tools/seed/seed-demo.py --no-activity</code>), plus un second magasin fictif : « Le Petit Bistrot Lille (démo) » en euros (captures 02 à 06), remplacé ensuite par « Le Petit Bistrot Tunis (démo) » en dinars (captures 01 et 07, cas « plusieurs devises »). Chrome headless 1280 × 900 (×2), clair et sombre, français et arabe (<code>*.ar.webp</code>). Aucun appareil mobile : l&#39;écran est un écran de back-office.</p><p>Mise en scène : références ajoutées aux produits de démo (BOI-020, VIN-001, CAF-002), surcharge de TVA (20 %) et de prix (2,80) du magasin de Lille, produit « Welsh lillois » créé pour Lille seul par l&#39;import lui-même. Le fichier <code>catalogue-printemps.csv</code> (4 créations, 4 mises à jour) sert aux captures 02 à 06 ; <code>catalogue-tunis.csv</code> (3 créations, TVA 19 et 7 %) aux captures 01 et 07. Les captures 02 à 05 précèdent l&#39;application ; l&#39;application a lieu une seule fois (4 créations, 4 mises à jour, 1 catégorie) pour produire l&#39;entrée du journal de la capture 06. Pour la capture 05, un script du scénario modifie le prix de deux produits par l&#39;API entre l&#39;analyse et « Appliquer », puis les remet.</p><p>Chaque capture existe en quatre variantes : <code>NN-nom.webp</code> (français, clair), <code>NN-nom.sombre.webp</code>, <code>NN-nom.ar.webp</code> (arabe, RTL), <code>NN-nom.sombre.ar.webp</code>. Mêmes images que celles du centre d&#39;aide (<code>help/public/captures/catalogue/importer-catalogue-csv/08</code> à <code>14</code>).</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+o+'" alt=""></td><td>Critère 13. Le fichier de Tunis analysé alors que les magasins ont deux devises : (1) liste « Nouveaux produits pour » au-dessus du fichier, (2) bandeau « choisissez le magasin », (3) « Analyser à nouveau » qui garde le fichier. Les trois lignes sont en erreur, rien n&#39;est écrit.</td></tr><tr><td><img src="'+i+'" alt=""></td><td>Critère 13. Aperçu de quatre créations « pour tous les magasins » : (1) « Prix TTC en EUR — pour tous les magasins », (2) taux « TVA intermédiaire 10 % (taux par défaut) » pour une cellule vide, (3) prix TTC formaté, (4) note « Prix de vente à 0 ».</td></tr><tr><td><img src="'+c+'" alt=""></td><td>Critère 14. Encadré « Ce fichier change la TVA de produits existants » : (1) liste « Jus de pomme : 10 % → 5,5 % », « Verre de vin blanc : 20 % → 10 % », (2) case « Je confirme le changement de TVA de 2 produits », (3) « Appliquer » grisé tant que la case n&#39;est pas cochée.</td></tr><tr><td><img src="'+n+'" alt=""></td><td>Critère 14. Notes de ligne : (1) « Lille garde sa TVA surchargée (20 %) », (2) « Lille garde son prix surchargé (2,80 EUR) », (3) badge « Propre au magasin Le Petit Bistrot Lille (démo) » sur le produit créé pour Lille.</td></tr><tr><td><img src="'+l+'" alt=""></td><td>Critère 14. Après un changement de catalogue entre l&#39;analyse et l&#39;application : (1) « Le catalogue a changé depuis l&#39;analyse (lignes 8, 9) … rien n&#39;a été écrit », (2) « Analyser à nouveau ».</td></tr><tr><td><img src="'+d+'" alt=""></td><td>Critère 14. Journal d&#39;audit, détail de l&#39;entrée « Catalogue (CSV) / Import » : (1) l&#39;entrée de l&#39;import avec ses changements de TVA, (2) la mention « Import CSV « catalogue-printemps.csv » ». Les lignes dessous portent la même origine.</td></tr><tr><td><img src="'+u+'" alt=""></td><td>Critère 13 (complément). Même fichier de Tunis après choix du magasin : (1) magasin choisi, (2) « Prix TTC en TND — pour Le Petit Bistrot Tunis (démo) », (3) taux, (4) prix en dinars à trois décimales (4,500 DT), badge « Propre au magasin ».</td></tr></tbody></table><p>Critère 15 (aide) : les captures 01 à 06 remplacent les marqueurs <code>CAPTURE-A-VENIR import-prealable-01</code> à <code>06</code> des trois pages <code>help/guide/catalogue/importer-catalogue-csv.md</code> (fr, en, ar) ; la 07 est ajoutée après la 01. <code>npm run coverage:strict</code> et <code>npm run build</code> sont verts.</p><h2 id="defauts-d1-a-d5-recapture-apres-correction-fusion-5ae879298" tabindex="-1">Défauts D1 à D5 : recapture après correction (fusion <code>5ae879298</code>) <a class="header-anchor" href="#defauts-d1-a-d5-recapture-apres-correction-fusion-5ae879298" aria-label="Permalink to &quot;Défauts D1 à D5 : recapture après correction (fusion `5ae879298`)&quot;">​</a></h2><p>Les images 01, 02, 05, 06 et 07 ont été refaites sur un serveur reconstruit depuis <code>main</code> à jour et une base neuve (même mise en scène, même fichier ; les captures 03 et 04, non touchées, sont inchangées). Vérifié à l&#39;œil :</p><ul><li><strong>D1 corrigé</strong> (05) : un seul bandeau rouge « Le catalogue a changé depuis l&#39;analyse (lignes 8, 9) … rien n&#39;a été écrit », avec « Analyser à nouveau » dedans ; le bandeau orange en double a disparu.</li><li><strong>D2 corrigé</strong> (01) : au rapport « magasin à choisir », plus de bandeau rouge « Corrigez les lignes en erreur » ; le bouton « Analyser à nouveau » est sous la phrase, qu&#39;il ne recouvre plus.</li><li><strong>D3 corrigé en partie</strong> (06) : la ligne « Import CSV « catalogue-printemps.csv » » est au-dessus du cadre JSON, entière, et les guillemets arabes sont à leur place. <strong>Reste</strong> : les clés techniques (<code>created</code>, <code>storeId</code>, <code>updated</code>…) s&#39;affichent encore en anglais dans la colonne Changements et dans le JSON, y compris en arabe, et la dernière ligne du cadre JSON (<code>],</code>) est coupée par son bord.</li><li><strong>D4 corrigé</strong> (01, 07) : en arabe, l&#39;étiquette est « إضافة المنتجات الجديدة إلى », complète.</li><li><strong>D5 corrigé</strong> (02, 07) : la colonne Détail est aérée, les lignes TVA / Prix TTC / notes se lisent sans se toucher. <strong>Reste</strong> (hors lot) : le nom de l&#39;auteur du journal montre la partie locale du compte de démo (« bistrot.cip »). En arabe, les pastilles 3 et 4 de la capture 07 touchent l&#39;en-tête « التفاصيل » (annotation, pas l&#39;écran).</li></ul></div>',3)])])}const C=r(p,[["render",m]]);export{T as __pageData,C as default};
